    top_module dut (
        .in0(in0),
        .in1(in1),
        .in2(in2),
        .in3(in3),
        .select(select),
        .out(out)
    );
    task testcase001;

    begin
        test_num = test_num + 1;
        $display("Test %0d: Select in0 (select=2'b00)", test_num);
        in0 = 4'h5; in1 = 4'hA; in2 = 4'h3; in3 = 4'hF;
        select = 2'b00;
        #1;

        check_outputs(4'h5);
    end
        endtask

    task testcase002;

    begin
        test_num = test_num + 1;
        $display("Test %0d: Select in1 (select=2'b01)", test_num);
        in0 = 4'h5; in1 = 4'hA; in2 = 4'h3; in3 = 4'hF;
