        #1;

        check_outputs(4'hA);
    end
        endtask

    task testcase003;

    begin
        test_num = test_num + 1;
        $display("Test %0d: Select in2 (select=2'b10)", test_num);
        in0 = 4'h5; in1 = 4'hA; in2 = 4'h3; in3 = 4'hF;
