        endtask

    task testcase004;

    begin
        test_num = test_num + 1;
        $display("Test %0d: Select in3 (select=2'b11)", test_num);
        in0 = 4'h5; in1 = 4'hA; in2 = 4'h3; in3 = 4'hF;
        select = 2'b11;
        #1;

        check_outputs(4'hF);
    end
        endtask

    task testcase005;

    begin
        test_num = test_num + 1;
        $display("Test %0d: All inputs logic high (4'hF)", test_num);
        in0 = 4'hF; in1 = 4'hF; in2 = 4'hF; in3 = 4'hF;
        select = 2'b10;
        #1;

        check_outputs(4'hF);
    end
        endtask

    task testcase006;

    begin
        test_num = test_num + 1;
        $display("Test %0d: All inputs logic low (4'h0)", test_num);
        in0 = 4'h0; in1 = 4'h0; in2 = 4'h0; in3 = 4'h0;
        select = 2'b01;
        #1;

        check_outputs(4'h0);
    end
        endtask

    task testcase007;

    begin
        test_num = test_num + 1;
        $display("Test %0d: Max 4-bit value on in3", test_num);
        in0 = 4'h1; in1 = 4'h2; in2 = 4'h4; in3 = 4'hF;
        select = 2'b11;
        #1;

        check_outputs(4'hF);
    end
        endtask

    task testcase008;

    begin
        test_num = test_num + 1;
        $display("Test %0d: Bit pattern 4'h9", test_num);
        in0 = 4'h9; in1 = 4'h6; in2 = 4'hC; in3 = 4'h3;
        select = 2'b00;
        #1;

        check_outputs(4'h9);
    end
        endtask

    // Test stimulus
    initial begin
        // Initialize
        test_num = 0;
        pass_count = 0;
        fail_count = 0;

        $display("========================================");
        $display("top_module Testbench");
        $display("========================================");


        testcase001();
        testcase002();
        testcase003();
        testcase004();
        testcase005();
        testcase006();
        testcase007();
        testcase008();


// Print summary
        $display("\n========================================");
        $display("Test Summary");
        $display("========================================");
        $display("Tests Passed: %0d", pass_count);
        $display("Tests Failed: %0d", fail_count);
        $display("Total Tests:  %0d", pass_count + fail_count);
        $display("========================================");

        if (fail_count == 0)
            $display("ALL TESTS PASSED!");
        else
            $display("SOME TESTS FAILED!");

        $display("\nSimulation completed at time %0t", $time);
        $finish;
    end

    // Task to check outputs
    task check_outputs;
        input [3:0] expected_out;
        begin
            #1; // Small delay for combinational logic to settle
