module shift_register_8bit(
    input clk,
    input load,
    input [7:0] data_in,
    output reg [7:0] q
);
    always @(posedge clk) begin
        if (load)
            q <= data_in;
        else
            q <= {q[6:0], 1'b0};
    end
endmodule

testbench:
`timescale 1ns/1ps

module shift_register_8bit_tb;

    // Testbench signals (sequential circuit)
    reg clk;
    reg [7:0] data_in;
    reg load;
    wire [7:0] q;

    // Test tracking
    integer test_num;
    integer pass_count;
    integer fail_count;

    // Instantiate the DUT (Device Under Test)
    shift_register_8bit dut (
        .clk(clk),
        .data_in(data_in),
        .load(load),
        .q(q)
    );

    // Clock generation (10ns period)
    initial begin
        clk = 0;
        forever #5 clk = ~clk;
    end

        task reset_dut;

        begin
            @(posedge clk);
            load <= 1;
            data_in <= 8'h00;
            @(posedge clk);
            load <= 0;
            data_in <= 8'h00;
            repeat(1) @(posedge clk);
        end
        endtask
    task testcase001;

        begin
            test_num = 1;
            $display("Testcase %03d: Parallel Load 8'hA5", test_num);
            reset_dut();

            @(posedge clk);
            load <= 1;
            data_in <= 8'hA5;
            @(posedge clk);
            load <= 0;

            #1;
            #1;

            check_outputs(8'hA5);
        end
        endtask

    task testcase002;

        begin
            test_num = 2;
            $display("Testcase %03d: Load 8'h01 then Shift Left once", test_num);
            reset_dut();

            @(posedge clk);
            load <= 1;
            data_in <= 8'h01;
            @(posedge clk);
            load <= 0;
            @(posedge clk);

            #1;
            #1;

            check_outputs(8'h02);
        end
        endtask

    task testcase003;

        begin
