            @(posedge clk);
            load <= 0;
            repeat(8) @(posedge clk);

            #1;
            #1;

            check_outputs(8'h00);
        end
        endtask

    task testcase005;

        begin
            test_num = 5;
            $display("Testcase %03d: Load 8'h80 then Shift (MSB disappears)", test_num);
            reset_dut();

            @(posedge clk);
            load <= 1;
            data_in <= 8'h80;
            @(posedge clk);
            load <= 0;
            @(posedge clk);

            #1;
            #1;

            check_outputs(8'h00);
        end
        endtask

    task testcase006;

        begin
            test_num = 6;
            $display("Testcase %03d: Load 0x55, Shift, then Load 0xEE", test_num);
            reset_dut();

            @(posedge clk);
            load <= 1;
            data_in <= 8'h55;
            @(posedge clk);
            load <= 0;
            @(posedge clk);
            load <= 1;
            data_in <= 8'hEE;
            @(posedge clk);
            load <= 0;

            #1;
            #1;

            check_outputs(8'hEE);
        end
        endtask

    // Test stimulus
