    10: SSEG_CA <= 8'b10001000; 
    11: SSEG_CA <= 8'b10000011; 
    12: SSEG_CA <= 8'b10100111; 
    13: SSEG_CA <= 8'b10100001; 
    14: SSEG_CA <= 8'b10000110; 
    15: SSEG_CA <= 8'b10001110; 
    endcase
  end
endmodule

