module top_module(
  input light_sensor,
  input clk,
  input rst,
  input [7:0] brightness,
  output reg led_out
);// Define brightness levels
  parameter [7:0] MAX_BRIGHTNESS = 8'hFF;
  parameter [7:0] MIN_BRIGHTNESS = 8'h00;
  parameter [7:0] AMBIENT_LIGHT_HIGH = 8'h80;
  parameter [7:0] AMBIENT_LIGHT_LOW = 8'h40;

  // Define state machine states
  parameter IDLE = 2'b00;
  parameter BRIGHTEN = 2'b01;
  parameter DIM = 2'b10;

  // Define state machine signals
  reg [1:0] state;
  reg [7:0] current_brightness;

  // Map photoresistor signal to brightness levels
  always @ (posedge clk) begin
    if (light_sensor >= AMBIENT_LIGHT_HIGH) begin
      current_brightness <= MAX_BRIGHTNESS;
    end else if (light_sensor <= AMBIENT_LIGHT_LOW) begin
      current_brightness <= MIN_BRIGHTNESS;
    end else begin
      current_brightness <= brightness;
    end
  end

  // State machine to control brightness of LED
  always @ (posedge clk) begin
    if (rst) begin
      state <= IDLE;
      led_out <= 0;
    end else begin
      case (state)
        IDLE: begin
          led_out <= 0;
          if (light_sensor >= AMBIENT_LIGHT_HIGH) begin
            state <= DIM;
          end else if (light_sensor <= AMBIENT_LIGHT_LOW) begin
            state <= BRIGHTEN;
          end
        end
        BRIGHTEN: begin
          led_out <= 1;
          current_brightness <= current_brightness + 1;
          if (current_brightness >= MAX_BRIGHTNESS) begin
            state <= IDLE;
          end
        end
        DIM: begin
          led_out <= 1;
          current_brightness <= current_brightness - 1;
          if (current_brightness <= MIN_BRIGHTNESS) begin
            state <= IDLE;
          end
        end
      endcase
    end
  end

endmodule

