module elevator (
	input clk,
	input resetn,
	input up,
	input down,
	output reg [3:0] floor);

	parameter IDLE=0, MOVING_UP=1, MOVING_DOWN=2;
	reg [1:0] state, next_state;

	always @(posedge clk) begin
		if (~resetn) state <= IDLE;
		else state <= next_state;
	end

	always @(posedge clk) begin
		case (state)
			MOVING_UP: floor <= floor + 1;
			MOVING_DOWN: floor <= floor - 1;
			default: floor <= floor;
		endcase
	end

	always_comb begin
		case (state)
			IDLE: next_state = up ? MOVING_UP : (down ? MOVING_DOWN : IDLE);
			MOVING_UP: next_state = up ? MOVING_UP : IDLE;
			MOVING_DOWN: next_state = down ? MOVING_DOWN : IDLE;
			default: next_state = IDLE;
		endcase
	end
endmodule

