module top_module(
  input               clk,
  input               rst_n,
  input               a,
  output reg          rise,
  output reg          down
);// Define the states for the state machine
  localparam IDLE = 2'b00;
  localparam RISING = 2'b01;
  localparam FALLING = 2'b10;

  // Define the current state and next state variables
  reg [1:0] state, next_state;

  // Define the rising and falling edge detection variables
  reg a_prev;
  reg a_curr;

  // Assign the initial state
  always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
      state <= IDLE;
    end else begin
      state <= next_state;
    end
  end

  // Define the state machine transitions and outputs
  always @(*) begin
    case (state)
      IDLE: begin
        if (a_curr && !a_prev) begin
          next_state = RISING;
          rise = 1'b1;
          down = 1'b0;
        end else if (!a_curr && a_prev) begin
          next_state = FALLING;
          rise = 1'b0;
          down = 1'b1;
        end else begin
          next_state = IDLE;
          rise = 1'b0;
          down = 1'b0;
        end
      end
      RISING: begin
        next_state = IDLE;
        rise = 1'b0;
        down = 1'b0;
      end
      FALLING: begin
        next_state = IDLE;
        rise = 1'b0;
        down = 1'b0;
      end
      default: begin
        next_state = IDLE;
        rise = 1'b0;
        down = 1'b0;
      end
    endcase
  end

  // Update the edge detection variables
  always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
      a_prev <= 1'b0;
      a_curr <= 1'b0;
    end else begin
      a_prev <= a_curr;
      a_curr <= a;
    end
  end

endmodule

