module elevator_controller (
    input clk,
    input resetn,
    input request,
    output reg [1:0] current_floor);

    parameter GROUND = 2'b00, FIRST = 2'b01, SECOND = 2'b10, THIRD = 2'b11;
    reg [1:0] state, next_state;

    always @(posedge clk) begin
        if (~resetn) state <= GROUND;
        else state <= next_state;
    end

    always_comb begin
        case (state)
            GROUND: next_state = request ? FIRST : GROUND;
            FIRST: next_state = request ? SECOND : GROUND;
            SECOND: next_state = request ? THIRD : GROUND;
            THIRD: next_state = request ? GROUND : THIRD;
            default: next_state = GROUND;
        endcase
    end

    always @(state) begin
        current_floor = state;
    end
endmodule

