module top_module (
  input in,
  input [1:0] state,
  output reg [1:0] next_state,
  output reg out);parameter X=0, Y=1, Z=2;

    always_comb begin
		case (state)
			X: next_state = in ? Y : X;
			Y: next_state = in ? X : Z;
			Z: next_state = in ? Z : Y;
		endcase
    end

    always_comb begin
		case (state)
			X: out = in ? 1 : 0;
			Y: out = in ? 0 : 1;
			Z: out = in ? 1 : 0;
		endcase
    end

endmodule

