module piso_shift_register_8bit (serial_out, clk, reset, en, load, parallel_in);
   input clk, reset, en, load;
   input [7:0] parallel_in;
   output serial_out;

   reg [7:0] shift_reg;

   assign serial_out = shift_reg[0];

