description:
Design a sign extension module that processes a 32-bit input, denoted as `data_i`, to produce a 32-bit output, `data_o`. This module examines the opcode from the top 7 bits of `data_i` and applies sign extension based on the specific instruction type. For opcodes such as addition (opcode `0010011`), store (opcode `0100011`), branch (opcode `1100011`), and load (opcode `0000011`), it extracts particular bits and extends the sign bit from `data_i` to fill the upper bits of `data_o`. If the opcode does not match any of the specified cases, the output defaults to zero.
module top_module(
    data_i,     
    data_o      
);

code:
module top_module(
    data_i,     
    data_o      
);input   [31:0]  data_i;
output [31:0]  data_o;

reg [31:0] data_o;

always@(data_i)
    begin
        case (data_i[6:0])
            7'b0010011: data_o = {{20{data_i[31]}}, data_i[31:20]}; 
            7'b0100011: data_o = {{20{data_i[31]}}, data_i[31:25], data_i[11:7]}; 
            7'b1100011: data_o = {{20{data_i[31]}}, data_i[31], data_i[7], data_i[30:25], data_i[11:8]}; 
            7'b0000011: data_o = {{20{data_i[31]}}, data_i[31:20]}; 
            default: data_o = 0;
        endcase        
    end


endmodule

