module top_module (
  input in1,
  input in2,
  input [1:0] state,
  output reg [1:0] next_state,
  output reg out);parameter G=0, H=1, I=2;

    always_comb begin
		case (state)
			G: next_state = (in1 || in2) ? I : H;
			H: next_state = (in1 || in2) ? G : I;
			I: next_state = (in1 || in2) ? H : G;
