description:
Design a finite state machine (FSM) that transitions through a series of states: IDLE, S1, S2, S3, and DONE. The FSM is clock-driven and reset-active low, starting in the IDLE state and moving sequentially to the DONE state. An output signal, `ack`, is asserted when the FSM reaches the DONE state. Additionally, the current state is represented in an ASCII format for debugging purposes, outputting descriptive strings for each state. This module effectively manages a simple sequence of operations, signaling completion via the `ack` output.
module top_module(
                             input  clk,
                             input  rst_n,
                             output ack
                             );

code:
module top_module(
                             input  clk,
                             input  rst_n,
                             output ack
                             );localparam // synopsys enum state_info
     IDLE  = 0,
     S1    = 1,
     S2    = 2,
     S3    = 3,
     DONE  = 4;

   reg [4:0] // synopsys enum state_info
             cur_state, nxt_state;

   always @ (*) begin
      nxt_state  = 5'h0;

      case (1'b1)
        cur_state[IDLE] : nxt_state[S1]    = 1'b1;
        cur_state[S1]   : nxt_state[S2]    = 1'b1;
        cur_state[S2]   : nxt_state[S3]    = 1'b1;
        cur_state[S3]   : nxt_state[DONE]  = 1'b1;
        cur_state[DONE] : nxt_state[DONE]  = 1'b1;
      endcase
   end

   always @ (posedge clk or negedge rst_n)
     if (rst_n == 1'b0) begin
        cur_state <= 'h1;
     end
     else begin
        cur_state <= nxt_state;
     end

   assign ack  = cur_state[DONE];

   /*AUTOASCIIENUM("cur_state", "cur_state_ascii")*/
   // Beginning of automatic ASCII enum decoding
   reg [31:0] cur_state_ascii;  // Decode of cur_state
   always @(cur_state) begin
