module top_module(
    input CLK,
    output flag
    );reg [5:0] cnt = 6'b0;
    reg flag_reg;
    always @ (posedge CLK)
        begin
            if (cnt == 6'd50)
                begin
                    flag_reg <= 1'b1;
                    cnt <= 1'b0;
                end
            else if (cnt == 1)
                begin
                    flag_reg <= 1'b0;
                    cnt <= cnt + 1'b1;
                end
            else
                cnt <= cnt + 1'b1;
        end
    assign flag = flag_reg;
endmodule

