module top_module(

   din,

   pad,

   dout, oe, ie
   );output din;
   input  dout;
   input  oe;
   input  ie;

   inout  pad;








   assign pad = oe ? dout : 1'bz;
   assign din = ie ? pad : 1'b0;

endmodule

